import { useCallback } from 'react';
import { z } from 'zod';
import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { SuperAppCommandOutbound, SuperAppResultCode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { generateUrl } from '~/shared/lib/utils/generate-url';
import { RsaOaep } from '~/shared/lib/utils/rsa-oaep';

type SendCommandParams = {
  command: SuperAppCommandOutbound;
  data?: SuperAppEncData;
  resultCode?: SuperAppResultCode;
  sendURL?: string;
};

const CommandTypeSchema = z.nativeEnum(SuperAppCommandOutbound);

const validateCommandType = (command: SuperAppCommandOutbound) => {
  const result = CommandTypeSchema.safeParse(command);
  if (!result.success) {
    console.error(`Invalid command type: ${command}`);
  }
  return result.success ? result.data : SuperAppCommandOutbound.슈퍼앱_에러콜백;
};

export const useSendSuperAppCommand = () => {
  const { openAlertDialog } = useAlertDialog();
  const { encryptText } = RsaOaep();

  const redirectWithError = useCallback((callback: string) => {
    const errorUrl = generateUrl({
      baseUrl: callback,
      command: SuperAppCommandOutbound.슈퍼앱_에러콜백,
      superAppCallback: callback,
      resultCode: SuperAppResultCode.메세지복호화실패,
    });

    useStore.getState().superAppSlice.clearSuperAppData();
    window.location.replace(errorUrl);
  }, []);

  const showErrorAndRedirect = useCallback(
    (callback?: string) => {
      openAlertDialog({
        message: i18n.t('text:signErrorText'),
        onConfirmClick: () => {
          if (!callback) return;
          redirectWithError(callback);
        },
      });
    },
    [openAlertDialog, redirectWithError],
  );

  const prepareCommandData = useCallback(
    (command: SuperAppCommandOutbound, data?: SuperAppEncData, resultCode?: SuperAppResultCode) => {
      const { decData } = useStore.getState().superAppSlice;
      if (!decData) throw new Error('No decoded data available');

      const validatedCommand = validateCommandType(command);

      const baseData: SuperAppEncData = {
        ...decData,
        command: validatedCommand,
        resultCode: resultCode ?? null,
      };

      if (!data) return baseData;

      return {
        ...baseData,
        ...data,
        command: validatedCommand,
        resultCode: resultCode ?? data.resultCode ?? null,
      };
    },
    [],
  );

  const sendSuperAppCommand = async ({ command, data, resultCode, sendURL }: SendCommandParams) => {
    const { decData, clearSuperAppData } = useStore.getState().superAppSlice;
    const callback = sendURL ?? decData?.superAppCallback;

    if (!callback) {
      openAlertDialog({
        message: '400 : 잘못된 요청',
        onConfirmClick: () => {
          useStore.getState().superAppSlice.clearSuperAppData();
          window.history.back();
        },
      });
      return;
    }

    try {
      const commandData = prepareCommandData(command, data, resultCode);
      const { encData: encryptedData, signature } = await encryptText(commandData);

      const url = generateUrl({
        baseUrl: callback,
        encData: encryptedData,
        signature,
        command: commandData.command ?? null,
        superAppCallback: callback,
        resultCode: commandData.resultCode ?? null,
      });

      clearSuperAppData();
      window.location.replace(url);
    } catch (error) {
      showErrorAndRedirect(callback);
    }
  };

  return { sendSuperAppCommand };
};
